// Adapter from `KeepsayCore` to the UniFFI-generated bindings of
// keepsay-core (core/src/ffi.rs, docs/changes/0014, 0019). Compiled only
// when apple/scripts/build-core.sh produced the XCFramework and
// `Sources/KeepsayCoreBindings/keepsay_core.swift` (generated by the
// workspace tool `keepsay-uniffi-bindgen`, never edited by hand).
//
// Threading: every FFI function blocks. Network, STT and file-copy calls
// (store/verify key, polish, transcribe, download, import) run on a detached
// task, never on the main thread. The small local reads (has_key,
// key_fingerprint, budget_status, get/save_settings, list_models) read a
// Keychain attribute or a small JSON file and are called directly.
//
// INV-2: no function here returns the key; `storeKey` hands it to core once.
// Never log or print transcripts, model output or the glossary: the
// generated records (`Settings`, `PolishOptions`, ...) have default
// descriptions that would print them.

#if canImport(KeepsayCoreBindings)
import Foundation
import KeepsayCoreBindings

final class UniffiCore: KeepsayCore, @unchecked Sendable {
    private let initError: CoreFailure?
    /// Swift-only preference (not in config.json, docs/changes/0019).
    private let lock = NSLock()
    private var alwaysEnableFallbackHotkeys = false

    convenience init() {
        var dir: URL?
        var failure: CoreFailure?
        do {
            dir = try Self.dataDirectory()
        } catch {
            failure = .io
        }
        self.init(dataDirectory: dir, failure: failure)
    }

    /// `dataDirectory` holds config.json, budget.json and models/.
    init(dataDirectory: URL?, failure: CoreFailure? = nil) {
        var failure = failure
        if let dir = dataDirectory, failure == nil {
            do {
                try KeepsayCoreBindings.`init`(dataDir: dir.path)
                try KeepsayCoreBindings.setUtcOffset(seconds: Int32(TimeZone.current.secondsFromGMT()))
            } catch {
                failure = Self.map(error)
            }
        }
        initError = failure
    }

    /// Application Support/dev.rightson.keepsay: the same directory as
    /// keepsay-cli's default on macOS (PROPOSAL §10); on iOS it is inside
    /// the app container.
    static func dataDirectory() throws -> URL {
        let base = try FileManager.default.url(
            for: .applicationSupportDirectory, in: .userDomainMask, appropriateFor: nil, create: true)
        let dir = base.appendingPathComponent("dev.rightson.keepsay", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }

    /// Runs a blocking FFI call on a background thread.
    private static func offMain<T: Sendable>(_ body: @escaping @Sendable () throws -> T) async throws -> T {
        try await Task.detached(priority: .userInitiated) {
            do { return try body() } catch { throw UniffiCore.map(error) }
        }.value
    }

    private func checkInit() throws {
        if let initError { throw initError }
    }

    // MARK: key (FR-1, INV-2)

    func storeKey(_ key: String) async throws -> String {
        try checkInit()
        return try await Self.offMain { try KeepsayCoreBindings.storeKey(key: key) }
    }

    func hasKey() -> Bool { KeepsayCoreBindings.hasKey() }
    func keyFingerprint() -> String? { KeepsayCoreBindings.keyFingerprint() }

    func deleteKey() throws {
        try checkInit()
        do { try KeepsayCoreBindings.deleteKey() } catch { throw Self.map(error) }
    }

    func verifyKey() async throws {
        try checkInit()
        try await Self.offMain { try KeepsayCoreBindings.verifyKey() }
    }

    // MARK: dictation

    func polish(_ transcript: String, request: PolishRequest) async throws -> PolishOutcome {
        if initError != nil {
            // Same rule as core: never lose the transcript.
            return .raw(transcript, cause: request.needsAPI ? (request.translateTo != nil ? .translationNeedsAPI : .noKey) : nil)
        }
        let opts = PolishOptions(
            mode: Self.mode(request.mode), translateTo: request.translateTo.map(Self.target),
            glossary: request.glossary)
        let r = try await Self.offMain { try KeepsayCoreBindings.polish(transcript: transcript, opts: opts) }
        return PolishOutcome(
            text: r.text, fellBackToRaw: r.fellBackToRaw, fallbackCause: r.fallbackReason.map(Self.cause),
            usage: r.usage.map { TokenUsage(inputTokens: $0.inputTokens, outputTokens: $0.outputTokens) })
    }

    func transcribe(pcm: [Float], sampleRate: UInt32, glossary: [String]) async throws -> String {
        try checkInit()
        let opts = SttOptions(language: "zh-TW", glossary: glossary)
        return try await Self.offMain {
            try KeepsayCoreBindings.transcribe(pcm: pcm, sampleRate: sampleRate, opts: opts)
        }
    }

    // MARK: budget, models

    func budgetStatus() -> BudgetSnapshot {
        guard let b = try? KeepsayCoreBindings.budgetStatus() else {
            // Unknown spend reads as "at the hard limit" (docs/changes/0009).
            return BudgetSnapshot(
                usage: TokenUsage(inputTokens: 0, outputTokens: 0), estimatedUSD: 0, softLimitUSD: nil,
                hardLimitUSD: 0)
        }
        return BudgetSnapshot(
            usage: TokenUsage(inputTokens: b.monthUsage.inputTokens, outputTokens: b.monthUsage.outputTokens),
            estimatedUSD: b.estimatedUsd, softLimitUSD: b.softLimitUsd, hardLimitUSD: b.hardLimitUsd)
    }

    func models() -> [ModelInfo] {
        guard let list = try? KeepsayCoreBindings.listModels() else { return [] }
        return list.map { ModelInfo(id: $0.id, name: $0.name, sizeBytes: $0.size, installed: $0.installed) }
    }

    func downloadModel(id: String, progress: @escaping @Sendable (Double) -> Void) async throws {
        try checkInit()
        let sink = ProgressSink(progress)
        try await Self.offMain { try KeepsayCoreBindings.downloadModel(id: id, progress: sink) }
    }

    func importModel(id: String, from url: URL) async throws {
        try checkInit()
        let path = url.path
        try await Self.offMain { try KeepsayCoreBindings.importModel(id: id, path: path) }
    }

    // MARK: settings (core's config.json is the only store)

    func loadSettings() -> AppSettings {
        lock.lock()
        let always = alwaysEnableFallbackHotkeys
        lock.unlock()
        guard let s = try? KeepsayCoreBindings.getSettings() else {
            var d = AppSettings()
            d.alwaysEnableFallbackHotkeys = always
            return d
        }
        return Self.appSettings(s, alwaysEnableFallbackHotkeys: always)
    }

    func saveSettings(_ settings: AppSettings) throws {
        try checkInit()
        lock.lock()
        alwaysEnableFallbackHotkeys = settings.alwaysEnableFallbackHotkeys
        lock.unlock()
        do {
            try KeepsayCoreBindings.saveSettings(settings: Self.coreSettings(settings))
        } catch {
            throw Self.map(error)
        }
    }

    // MARK: conversions

    static func appSettings(_ s: KeepsayCoreBindings.Settings, alwaysEnableFallbackHotkeys: Bool) -> AppSettings {
        AppSettings(
            mode: dictationMode(s.mode),
            translateTo: translationTarget(s.translateTo),
            sttModel: s.sttModel,
            glossary: s.glossary,
            prices: PriceTable(inputUSDPerMTok: s.inputUsdPerMtok, outputUSDPerMTok: s.outputUsdPerMtok),
            softLimitUSD: s.softLimitUsd,
            hardLimitUSD: s.hardLimitUsd,
            alwaysEnableFallbackHotkeys: alwaysEnableFallbackHotkeys,
            fallbackPolish: s.hotkeyPolish.flatMap(KeyCombo.init(configString:)) ?? .fallbackPolish,
            fallbackTranslate: s.hotkeyPolishTranslate.flatMap(KeyCombo.init(configString:)) ?? .fallbackTranslate)
    }

    static func coreSettings(_ a: AppSettings) -> KeepsayCoreBindings.Settings {
        KeepsayCoreBindings.Settings(
            mode: mode(a.mode),
            translateTo: target(a.translateTo),
            sttModel: a.sttModel,
            glossary: a.glossary,
            inputUsdPerMtok: a.prices.inputUSDPerMTok,
            outputUsdPerMtok: a.prices.outputUSDPerMTok,
            softLimitUsd: a.softLimitUSD,
            hardLimitUsd: a.hardLimitUSD,
            // `None` = platform default (⌥Space / ⌥⇧Space), FR-2.
            hotkeyPolish: a.fallbackPolish == .fallbackPolish ? nil : a.fallbackPolish.configString,
            hotkeyPolishTranslate: a.fallbackTranslate == .fallbackTranslate ? nil : a.fallbackTranslate.configString)
    }

    static func mode(_ m: DictationMode) -> Mode {
        switch m {
        case .raw: .raw
        case .light: .light
        case .polish: .polish
        case .formal: .formal
        }
    }

    static func dictationMode(_ m: Mode) -> DictationMode {
        switch m {
        case .raw: .raw
        case .light: .light
        case .polish: .polish
        case .formal: .formal
        }
    }

    static func target(_ t: TranslationTarget) -> TargetLang {
        switch t {
        case .en: .en
        case .zhTW: .zhTw
        case .ja: .ja
        }
    }

    static func translationTarget(_ t: TargetLang) -> TranslationTarget {
        switch t {
        case .en: .en
        case .zhTw: .zhTW
        case .ja: .ja
        }
    }

    static func cause(_ r: FallbackReason) -> FallbackCause {
        switch r {
        case .translationNeedsApi: .translationNeedsAPI
        case .noKey: .noKey
        case .keyInvalid: .keyInvalid
        case .hardLimit: .hardLimit
        case .budgetExhausted: .budgetExhausted
        case .network: .network
        case .timeout: .timeout
        case .rateLimited: .rateLimited
        case .apiError: .apiError
        case .guardRejected: .guardRejected
        }
    }

    /// Flat UniFFI errors carry core's `Display` text, which never holds
    /// secrets or user content; it is dropped here anyway.
    static func map(_ error: Error) -> CoreFailure {
        if let f = error as? CoreFailure { return f }
        guard let e = error as? CoreError else { return .io }
        switch e {
        case .KeyInvalid: return .keyInvalid
        case .KeyFormat: return .keyFormat
        case .KeyNotFound: return .keyNotFound
        case .VaultUnavailable: return .vaultUnavailable
        case .VaultNotEntitled: return .unsupported
        case .DisallowedHost: return .disallowedHost
        case .Network: return .network
        case .Timeout: return .timeout
        case .RateLimited: return .rateLimited
        case .BudgetExhausted: return .budgetExhausted
        case .ApiStatus: return .apiStatus(0)
        case .InvalidResponse: return .invalidResponse
        case .ModelNotAllowed: return .modelNotAllowed
        case .GuardRejected: return .guardRejected
        case .HardLimitReached: return .hardLimitReached
        case .AudioFormat: return .audioFormat
        case .Stt: return .stt
        case .ModelUnknown: return .modelUnknown
        case .ModelHash: return .modelHash
        case .ModelTooLarge: return .modelTooLarge
        case .Config: return .config
        case .Io: return .io
        case .Unsupported: return .unsupported
        case .NotInitialized: return .coreNotLinked
        }
    }
}

/// Swift side of core's foreign `DownloadProgress` trait (two numbers only).
private final class ProgressSink: DownloadProgress, @unchecked Sendable {
    private let report: @Sendable (Double) -> Void

    init(_ report: @escaping @Sendable (Double) -> Void) {
        self.report = report
    }

    func onProgress(received: UInt64, total: UInt64) {
        report(total == 0 ? 0 : min(1, Double(received) / Double(total)))
    }
}
#endif
